package com.amit.jobagent.application;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity@Table(name="application_submission_report")class ApplicationSubmissionReport{@Id UUID id;@Column(name="application_handoff_id",nullable=false,updatable=false)UUID handoffId;@Column(name="actor_id",nullable=false,updatable=false,length=150)String actor;@Enumerated(EnumType.STRING)@Column(nullable=false,updatable=false,length=40)SubmissionAction action;@Column(name="external_reference",updatable=false,length=200)String externalReference;@Column(updatable=false,length=1000)String note;@Column(name="reported_submission_at",updatable=false)Instant reportedAt;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="idempotency_key_hash",unique=true,updatable=false,length=64,columnDefinition="char(64)")String idempotencyHash;@Column(name="created_at",nullable=false,updatable=false)Instant createdAt;protected ApplicationSubmissionReport(){}ApplicationSubmissionReport(UUID handoff,String actor,SubmissionAction action,String ref,String note,Instant reported,String key){id=UUID.randomUUID();handoffId=handoff;this.actor=actor;this.action=action;externalReference=ref;this.note=note;reportedAt=reported;idempotencyHash=key;createdAt=Instant.now();}}
